from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import issue_credit_note
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(status="issued", total="1000.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("x",1,Decimal(total))],status=status)

# basic + audit
n = issue_credit_note(inv(), Decimal("10.00"), "goodwill", idempotency_key="k1")
print(n, audit.events("credit_note_issued"))
# idempotent replay
n2 = issue_credit_note(inv(), Decimal("10.00"), "goodwill", idempotency_key="k1")
print("replay", n2, "events", len(audit.events("credit_note_issued")))
# approval
try:
    issue_credit_note(inv(), Decimal("600.00"), "x")
except BillingError as e: print("approval:", e.code)
print(issue_credit_note(inv(), Decimal("600.00"), "x", approved_by="boss")["amount"])
print(issue_credit_note(inv(), Decimal("500.00"), "x")["amount"])
# invalid state
try:
    issue_credit_note(inv("draft"), Decimal("1.00"), "x")
except BillingError as e: print("state:", e.code)
# exceeds
try:
    issue_credit_note(inv(total="5.00"), Decimal("6.00"), "x")
except BillingError as e: print("exceeds:", e.code)
# non-positive
try:
    issue_credit_note(inv(), Decimal("0"), "x")
except BillingError as e: print("nonpos:", e.code)
EOF"}

